@roblox/globaltype/RecommendationService.code_sample:
local RecommendationService = game:GetService("RecommendationService")

-- Öneri listesi oluşturma isteğini tanımlayın
local request: GenerateRecommendationItemListRequest = {
	ConfigName = "MaximizeEngagement",
	LocationId = "Lobby",
	PageSize = 10
    -- NOT: Sunucu scripti için CustomContexts.UserId'yi açın ve ayarlayın. 
    -- Yerel script için ayarlamaya gerek yok.
    -- CustomContexts = {
    --     ["UserId"] = tostring(player.UserId),
    -- }
}

-- Öneri sayfalarını almak için GenerateItemListAsync'ı çağırın
local success, recommendationPages = pcall(function()
    return RecommendationService:GenerateItemListAsync(request)
end)

